insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c14d4408-ebb4-4a77-a3b0-fe58cbe3efaf', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Course Orientation, Feedback Concepts, and Control Objectives', 'This opening unit explains why feedback is powerful: it can make systems accurate, stable, robust, and responsive despite disturbances and uncertainty. Students learn the vocabulary used throughout the course.', 0),
  ('4e147c6d-c8ba-4374-ae5c-87d6bb957c85', '45241651-6d27-44f7-8908-f941a7418479', 'c14d4408-ebb4-4a77-a3b0-fe58cbe3efaf', 'subtopic'::public.curated_course_node_type, 'Open-Loop and Closed-Loop Control', 'Students learn the difference between commanding a system blindly and using measured output to correct behavior.', 0),
  ('bbf36f38-c91d-410c-92f4-6d2224f94d3c', '45241651-6d27-44f7-8908-f941a7418479', '4e147c6d-c8ba-4374-ae5c-87d6bb957c85', 'concept'::public.curated_course_node_type, 'Open-loop control and feedforward ideas', null, 0),
  ('d224381e-8805-4fae-b70b-8c68f4d72725', '45241651-6d27-44f7-8908-f941a7418479', '4e147c6d-c8ba-4374-ae5c-87d6bb957c85', 'concept'::public.curated_course_node_type, 'Closed-loop feedback control', null, 1),
  ('b873da92-af4c-4294-913f-f86af633678d', '45241651-6d27-44f7-8908-f941a7418479', '4e147c6d-c8ba-4374-ae5c-87d6bb957c85', 'concept'::public.curated_course_node_type, 'Disturbance rejection and reference tracking', null, 2),
  ('a435036b-4aff-4d14-9b69-8c40f549009d', '45241651-6d27-44f7-8908-f941a7418479', 'c14d4408-ebb4-4a77-a3b0-fe58cbe3efaf', 'subtopic'::public.curated_course_node_type, 'Control Objectives and Tradeoffs', 'Control design is a negotiation among speed, stability, accuracy, robustness, effort, and noise sensitivity.', 1),
  ('2ccc8d31-be24-407e-b1c0-b225268e4680', '45241651-6d27-44f7-8908-f941a7418479', 'a435036b-4aff-4d14-9b69-8c40f549009d', 'concept'::public.curated_course_node_type, 'Rise time, settling time, overshoot, steady-state error', null, 0),
  ('028a3a3b-fa8c-4f51-88a1-501bdc840eb0', '45241651-6d27-44f7-8908-f941a7418479', 'a435036b-4aff-4d14-9b69-8c40f549009d', 'concept'::public.curated_course_node_type, 'Stability margins and robustness', null, 1),
  ('b286e1bd-05b3-4e49-9de9-a07cb1f182ba', '45241651-6d27-44f7-8908-f941a7418479', 'a435036b-4aff-4d14-9b69-8c40f549009d', 'concept'::public.curated_course_node_type, 'Actuator limits, sensor noise, and design compromises', null, 2),
  ('ce2ed820-11b7-49e9-8e04-71eaa8f86b4a', '45241651-6d27-44f7-8908-f941a7418479', 'c14d4408-ebb4-4a77-a3b0-fe58cbe3efaf', 'subtopic'::public.curated_course_node_type, 'Control System Examples', 'Examples make abstract diagrams concrete by showing control in electrical, mechanical, thermal, process, aerospace, and robotic systems.', 2),
  ('4eef9a5c-7179-41c8-8b02-076a4bd3ade9', '45241651-6d27-44f7-8908-f941a7418479', 'ce2ed820-11b7-49e9-8e04-71eaa8f86b4a', 'concept'::public.curated_course_node_type, 'Cruise control, motor speed, temperature, liquid level', null, 0),
  ('641273e4-eee6-4163-92c7-2d009b36313a', '45241651-6d27-44f7-8908-f941a7418479', 'ce2ed820-11b7-49e9-8e04-71eaa8f86b4a', 'concept'::public.curated_course_node_type, 'Aircraft autopilot and spacecraft attitude control', null, 1),
  ('42ec8a42-d6eb-48da-a6a4-e92014e853b8', '45241651-6d27-44f7-8908-f941a7418479', 'ce2ed820-11b7-49e9-8e04-71eaa8f86b4a', 'concept'::public.curated_course_node_type, 'Embedded and cyber-physical control loops', null, 2),
  ('8b68aa9e-68ea-41fa-b129-5b1bc1772f21', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Dynamic System Modeling Across Domains', 'Controls begins with models. This unit teaches students to represent physical systems with equations that capture how inputs, states, and outputs evolve over time.', 1),
  ('16e2ec1f-de31-478a-bef8-1e8d5f399476', '45241651-6d27-44f7-8908-f941a7418479', '8b68aa9e-68ea-41fa-b129-5b1bc1772f21', 'subtopic'::public.curated_course_node_type, 'Mechanical, Electrical, Thermal, and Fluid Analogies', 'Students learn common modeling patterns that transfer across engineering domains.', 0),
  ('53686f46-72f8-4a25-b7ec-966a31b67e20', '45241651-6d27-44f7-8908-f941a7418479', '16e2ec1f-de31-478a-bef8-1e8d5f399476', 'concept'::public.curated_course_node_type, 'Mass-spring-damper systems', null, 0),
  ('a2977f86-07aa-4f34-a021-01668b1f183e', '45241651-6d27-44f7-8908-f941a7418479', '16e2ec1f-de31-478a-bef8-1e8d5f399476', 'concept'::public.curated_course_node_type, 'RLC circuits and electromechanical motors', null, 1),
  ('c4cf7687-4401-452f-89e8-5ff127f45979', '45241651-6d27-44f7-8908-f941a7418479', '16e2ec1f-de31-478a-bef8-1e8d5f399476', 'concept'::public.curated_course_node_type, 'Thermal capacitance/resistance and fluid tanks', null, 2),
  ('07711d27-5681-4d3f-afcd-da06965436fc', '45241651-6d27-44f7-8908-f941a7418479', '8b68aa9e-68ea-41fa-b129-5b1bc1772f21', 'subtopic'::public.curated_course_node_type, 'Input, Output, State, and Disturbance Variables', 'Clear variable definitions keep models connected to measurable and controllable quantities.', 1),
  ('6fb8087c-7aae-46f1-869f-945b9fa1687f', '45241651-6d27-44f7-8908-f941a7418479', '07711d27-5681-4d3f-afcd-da06965436fc', 'concept'::public.curated_course_node_type, 'Inputs, outputs, states, parameters, disturbances', null, 0),
  ('5e375672-831c-48e2-b89e-2c9b5980e1b2', '45241651-6d27-44f7-8908-f941a7418479', '07711d27-5681-4d3f-afcd-da06965436fc', 'concept'::public.curated_course_node_type, 'Sensor and actuator placement', null, 1),
  ('a95b1cb7-f7ec-4abe-9dca-cfd99d9af85f', '45241651-6d27-44f7-8908-f941a7418479', '07711d27-5681-4d3f-afcd-da06965436fc', 'concept'::public.curated_course_node_type, 'Units, sign conventions, and assumptions', null, 2),
  ('98b395ba-95dd-4384-bd70-5dffd17a457d', '45241651-6d27-44f7-8908-f941a7418479', '8b68aa9e-68ea-41fa-b129-5b1bc1772f21', 'subtopic'::public.curated_course_node_type, 'Model Validation and Limits', 'A useful model is not necessarily complete. Students learn how to judge what is included and what is ignored.', 2),
  ('bd4b8f4e-b97e-42a5-b436-c7efebd78dd3', '45241651-6d27-44f7-8908-f941a7418479', '98b395ba-95dd-4384-bd70-5dffd17a457d', 'concept'::public.curated_course_node_type, 'Linearity, time invariance, lumped parameters', null, 0),
  ('32dbb4c3-ceb7-4eac-a7c2-ca477d1fc605', '45241651-6d27-44f7-8908-f941a7418479', '98b395ba-95dd-4384-bd70-5dffd17a457d', 'concept'::public.curated_course_node_type, 'Operating regions and approximation error', null, 1),
  ('865f879b-f589-4070-b435-415264835a24', '45241651-6d27-44f7-8908-f941a7418479', '98b395ba-95dd-4384-bd70-5dffd17a457d', 'concept'::public.curated_course_node_type, 'Experimental data and parameter estimation overview', null, 2),
  ('5bc19c05-cd5b-43a1-83a8-f63c61458c39', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Laplace Transforms, Transfer Functions, and Linearization', 'This unit converts differential-equation models into algebraic input-output relationships. Transfer functions become the language for classical control analysis and design.', 2),
  ('760a1be4-a16d-4005-a48f-9550f9d1f29f', '45241651-6d27-44f7-8908-f941a7418479', '5bc19c05-cd5b-43a1-83a8-f63c61458c39', 'subtopic'::public.curated_course_node_type, 'Laplace Transform Review', 'Students review the transform tools needed to solve linear dynamic systems and interpret poles and zeros.', 0),
  ('ebf642b3-19ed-44e6-99e7-9922763e0a3b', '45241651-6d27-44f7-8908-f941a7418479', '760a1be4-a16d-4005-a48f-9550f9d1f29f', 'concept'::public.curated_course_node_type, 'Laplace transform properties', null, 0),
  ('f2243b93-7fa8-4dc1-941e-5bd574edcd6d', '45241651-6d27-44f7-8908-f941a7418479', '760a1be4-a16d-4005-a48f-9550f9d1f29f', 'concept'::public.curated_course_node_type, 'Initial and final value theorems', null, 1),
  ('d81322fa-8717-4b87-9a79-ce278e2091b7', '45241651-6d27-44f7-8908-f941a7418479', '760a1be4-a16d-4005-a48f-9550f9d1f29f', 'concept'::public.curated_course_node_type, 'Partial fractions and inverse transforms', null, 2),
  ('a5d8e049-7b32-4dda-a712-dfaee66c77b1', '45241651-6d27-44f7-8908-f941a7418479', '5bc19c05-cd5b-43a1-83a8-f63c61458c39', 'subtopic'::public.curated_course_node_type, 'Transfer Functions', 'Transfer functions summarize how a linear time-invariant system maps inputs to outputs.', 1),
  ('57b1d2d2-8e33-4b5a-942b-01ba765fff81', '45241651-6d27-44f7-8908-f941a7418479', 'a5d8e049-7b32-4dda-a712-dfaee66c77b1', 'concept'::public.curated_course_node_type, 'Input-output ratio with zero initial conditions', null, 0),
  ('0b74fee9-9b70-4c60-9ab5-63ae089502d2', '45241651-6d27-44f7-8908-f941a7418479', 'a5d8e049-7b32-4dda-a712-dfaee66c77b1', 'concept'::public.curated_course_node_type, 'Poles, zeros, gain, and system order', null, 1),
  ('f756fc3d-33f3-4717-b206-99bc558e01b4', '45241651-6d27-44f7-8908-f941a7418479', 'a5d8e049-7b32-4dda-a712-dfaee66c77b1', 'concept'::public.curated_course_node_type, 'Proper and strictly proper transfer functions', null, 2),
  ('db15b045-fd0d-4ddd-80cc-2dab4dbb55f1', '45241651-6d27-44f7-8908-f941a7418479', '5bc19c05-cd5b-43a1-83a8-f63c61458c39', 'subtopic'::public.curated_course_node_type, 'Linearization Around Operating Points', 'Many real systems are nonlinear, so students learn how local linear models support classical control.', 2),
  ('8a9b0f0b-4725-459d-922e-cd5237b5bee9', '45241651-6d27-44f7-8908-f941a7418479', 'db15b045-fd0d-4ddd-80cc-2dab4dbb55f1', 'concept'::public.curated_course_node_type, 'Taylor-series linearization', null, 0),
  ('29105bb2-908f-4dc6-b64d-3fbb75b623c8', '45241651-6d27-44f7-8908-f941a7418479', 'db15b045-fd0d-4ddd-80cc-2dab4dbb55f1', 'concept'::public.curated_course_node_type, 'Equilibrium or trim points', null, 1),
  ('1b16ae8e-ecdf-4b15-b17a-7af9a38993c5', '45241651-6d27-44f7-8908-f941a7418479', 'db15b045-fd0d-4ddd-80cc-2dab4dbb55f1', 'concept'::public.curated_course_node_type, 'Small-signal models and limits of validity', null, 2),
  ('cf7dd000-fd4a-42b7-93d4-fead0a69c6c3', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Block Diagrams, Signal Flow Graphs, and Feedback Architecture', 'Control systems are often easier to reason about as interconnected blocks. This unit teaches how to reduce diagrams and identify the functional roles inside a loop.', 3),
  ('07edeca7-a0ef-4e95-b701-18ba9a5f4999', '45241651-6d27-44f7-8908-f941a7418479', 'cf7dd000-fd4a-42b7-93d4-fead0a69c6c3', 'subtopic'::public.curated_course_node_type, 'Block Diagram Algebra', 'Students learn to simplify series, parallel, and feedback interconnections into equivalent transfer functions.', 0),
  ('d8d056c7-74b3-44a5-891a-4ca44b7fafcc', '45241651-6d27-44f7-8908-f941a7418479', '07edeca7-a0ef-4e95-b701-18ba9a5f4999', 'concept'::public.curated_course_node_type, 'Cascade, parallel, and feedback reduction', null, 0),
  ('ccbaab9a-4010-4d07-81ef-b65cd9ab82b3', '45241651-6d27-44f7-8908-f941a7418479', '07edeca7-a0ef-4e95-b701-18ba9a5f4999', 'concept'::public.curated_course_node_type, 'Summing junctions and takeoff points', null, 1),
  ('882a0793-c7a1-4cd1-afd4-9888a93d7cdc', '45241651-6d27-44f7-8908-f941a7418479', '07edeca7-a0ef-4e95-b701-18ba9a5f4999', 'concept'::public.curated_course_node_type, 'Closed-loop transfer functions', null, 2),
  ('2b0c7550-2565-4416-8bb7-3518f466e258', '45241651-6d27-44f7-8908-f941a7418479', 'cf7dd000-fd4a-42b7-93d4-fead0a69c6c3', 'subtopic'::public.curated_course_node_type, 'Signal Flow Graphs', 'Signal flow graphs provide a systematic alternative for complex interconnections.', 1),
  ('456377b8-9d7a-4f0c-9791-cacedbff4746', '45241651-6d27-44f7-8908-f941a7418479', '2b0c7550-2565-4416-8bb7-3518f466e258', 'concept'::public.curated_course_node_type, 'Nodes, branches, loops, and paths', null, 0),
  ('414ab638-237c-4e41-82c5-fe75d397e1f7', '45241651-6d27-44f7-8908-f941a7418479', '2b0c7550-2565-4416-8bb7-3518f466e258', 'concept'::public.curated_course_node_type, 'Mason''s gain formula overview', null, 1),
  ('5e4d1208-9e30-49da-949a-9133648bec4e', '45241651-6d27-44f7-8908-f941a7418479', '2b0c7550-2565-4416-8bb7-3518f466e258', 'concept'::public.curated_course_node_type, 'Comparison with block diagram reduction', null, 2),
  ('26c6f9a8-d2dc-4134-9af9-ede08b5eb143', '45241651-6d27-44f7-8908-f941a7418479', 'cf7dd000-fd4a-42b7-93d4-fead0a69c6c3', 'subtopic'::public.curated_course_node_type, 'Feedback Architecture', 'Students learn how controllers, plants, sensors, actuators, references, and disturbances fit together.', 2),
  ('0d48f2f0-d0fc-4489-bcce-34d3c9706c62', '45241651-6d27-44f7-8908-f941a7418479', '26c6f9a8-d2dc-4134-9af9-ede08b5eb143', 'concept'::public.curated_course_node_type, 'Plant, controller, sensor, actuator, and comparator', null, 0),
  ('acdba629-acb8-4b7c-bad4-5236bac1f4d6', '45241651-6d27-44f7-8908-f941a7418479', '26c6f9a8-d2dc-4134-9af9-ede08b5eb143', 'concept'::public.curated_course_node_type, 'Unity and non-unity feedback', null, 1),
  ('f0dfe083-35af-4bb5-9a23-2e6f1c6595df', '45241651-6d27-44f7-8908-f941a7418479', '26c6f9a8-d2dc-4134-9af9-ede08b5eb143', 'concept'::public.curated_course_node_type, 'Sensitivity and complementary sensitivity preview', null, 2),
  ('05ba78d4-53c3-45ec-b5ce-65749a2a7b4c', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Time-Domain Response and Performance Specifications', 'This unit connects transfer functions to observable behavior over time. Students learn how system poles shape transients, steady-state response, and design specifications.', 4),
  ('514f28ba-7cc5-4171-bac2-84caff85f946', '45241651-6d27-44f7-8908-f941a7418479', '05ba78d4-53c3-45ec-b5ce-65749a2a7b4c', 'subtopic'::public.curated_course_node_type, 'First- and Second-Order System Response', 'Students learn canonical response shapes that appear repeatedly in engineering control systems.', 0),
  ('9b98e1b8-b688-42f3-9f4e-38651bbcb017', '45241651-6d27-44f7-8908-f941a7418479', '514f28ba-7cc5-4171-bac2-84caff85f946', 'concept'::public.curated_course_node_type, 'Impulse, step, and ramp responses', null, 0),
  ('be5ac7c9-e5d0-4b8d-8cda-f069cfea81d4', '45241651-6d27-44f7-8908-f941a7418479', '514f28ba-7cc5-4171-bac2-84caff85f946', 'concept'::public.curated_course_node_type, 'Time constant and natural frequency', null, 1),
  ('217bb252-21b5-40e2-961d-88487a8b6c6b', '45241651-6d27-44f7-8908-f941a7418479', '514f28ba-7cc5-4171-bac2-84caff85f946', 'concept'::public.curated_course_node_type, 'Damping ratio and dominant poles', null, 2),
  ('4622a872-2cdb-4cf1-9539-c4c41678824e', '45241651-6d27-44f7-8908-f941a7418479', '05ba78d4-53c3-45ec-b5ce-65749a2a7b4c', 'subtopic'::public.curated_course_node_type, 'Performance Measures', 'Design specifications turn a desired behavior into measurable targets.', 1),
  ('5e2e0916-097d-4fe4-b602-17a7389e1339', '45241651-6d27-44f7-8908-f941a7418479', '4622a872-2cdb-4cf1-9539-c4c41678824e', 'concept'::public.curated_course_node_type, 'Rise time, peak time, percent overshoot', null, 0),
  ('0cc5c68f-13ed-499f-970c-f73c1d5bff67', '45241651-6d27-44f7-8908-f941a7418479', '4622a872-2cdb-4cf1-9539-c4c41678824e', 'concept'::public.curated_course_node_type, 'Settling time and steady-state error', null, 1),
  ('37ef424c-9da7-4295-bc2b-1b1c7b40fd81', '45241651-6d27-44f7-8908-f941a7418479', '4622a872-2cdb-4cf1-9539-c4c41678824e', 'concept'::public.curated_course_node_type, 'Transient versus steady-state requirements', null, 2),
  ('23bd557a-2451-4bf5-aa0f-3e1e8e71af37', '45241651-6d27-44f7-8908-f941a7418479', '05ba78d4-53c3-45ec-b5ce-65749a2a7b4c', 'subtopic'::public.curated_course_node_type, 'Steady-State Error and System Type', 'Students learn how loop structure determines tracking accuracy for common inputs.', 2),
  ('e3a8dc7a-4a4b-48f0-bf8d-007c3f82c4ed', '45241651-6d27-44f7-8908-f941a7418479', '23bd557a-2451-4bf5-aa0f-3e1e8e71af37', 'concept'::public.curated_course_node_type, 'Position, velocity, and acceleration error constants', null, 0),
  ('a0399dcf-0ca5-48cc-aa46-0e0c6e2ca655', '45241651-6d27-44f7-8908-f941a7418479', '23bd557a-2451-4bf5-aa0f-3e1e8e71af37', 'concept'::public.curated_course_node_type, 'System type and integrators', null, 1),
  ('c4f1e009-436b-4e5d-8c0f-6cf0dfa51d81', '45241651-6d27-44f7-8908-f941a7418479', '23bd557a-2451-4bf5-aa0f-3e1e8e71af37', 'concept'::public.curated_course_node_type, 'Tracking step, ramp, and parabolic references', null, 2),
  ('bb5adaf9-24b1-4fe1-8a44-ecc041921226', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Stability Analysis and Routh-Hurwitz Criterion', 'Stability is the first requirement of useful feedback. This unit teaches students how to determine whether closed-loop poles produce bounded, reliable behavior.', 5),
  ('2dc10e89-b149-4424-bc98-c0b8aaeb7156', '45241651-6d27-44f7-8908-f941a7418479', 'bb5adaf9-24b1-4fe1-8a44-ecc041921226', 'subtopic'::public.curated_course_node_type, 'Pole Locations and Stability', 'Students connect pole position to whether a continuous-time system decays, oscillates, or grows.', 0),
  ('f47bc89e-d611-4c18-b963-03b052e889b4', '45241651-6d27-44f7-8908-f941a7418479', '2dc10e89-b149-4424-bc98-c0b8aaeb7156', 'concept'::public.curated_course_node_type, 'Left-half plane, right-half plane, and imaginary-axis poles', null, 0),
  ('9bfdec28-7c43-4629-a131-5aa247823b24', '45241651-6d27-44f7-8908-f941a7418479', '2dc10e89-b149-4424-bc98-c0b8aaeb7156', 'concept'::public.curated_course_node_type, 'Marginal and asymptotic stability', null, 1),
  ('7318eff2-9b71-4237-bcfa-f3b2248d892b', '45241651-6d27-44f7-8908-f941a7418479', '2dc10e89-b149-4424-bc98-c0b8aaeb7156', 'concept'::public.curated_course_node_type, 'Dominant poles and transient behavior', null, 2),
  ('83976747-b619-4c21-b6f9-032ccdb30835', '45241651-6d27-44f7-8908-f941a7418479', 'bb5adaf9-24b1-4fe1-8a44-ecc041921226', 'subtopic'::public.curated_course_node_type, 'Routh-Hurwitz Criterion', 'Routh-Hurwitz tests stability without explicitly solving high-order characteristic equations.', 1),
