  ('a8a40418-8f6a-4933-95bf-aa1ca7b296ab', '45241651-6d27-44f7-8908-f941a7418479', '9d65f851-38a5-44a8-bb2f-1772ad0ead4e', 'subtopic'::public.curated_course_node_type, 'Observability', 'Observability asks whether available measurements contain enough information to infer internal state.', 2),
  ('9211ddb0-7cc0-4d7a-bcde-006474f734b8', '45241651-6d27-44f7-8908-f941a7418479', 'a8a40418-8f6a-4933-95bf-aa1ca7b296ab', 'concept'::public.curated_course_node_type, 'Observability matrix', null, 0),
  ('c6c5e6eb-ece2-4493-b546-0e0bbffe7f6d', '45241651-6d27-44f7-8908-f941a7418479', 'a8a40418-8f6a-4933-95bf-aa1ca7b296ab', 'concept'::public.curated_course_node_type, 'Rank test and sensor placement', null, 1),
  ('4963769c-a56d-47f4-beef-3c4c82494cb1', '45241651-6d27-44f7-8908-f941a7418479', 'a8a40418-8f6a-4933-95bf-aa1ca7b296ab', 'concept'::public.curated_course_node_type, 'Unobservable modes and estimation limits', null, 2),
  ('88b58342-6025-4c1c-ac0b-455af456d4d5', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'State Feedback, Observers, and Estimation Overview', 'This unit shows how state-space models become controllers and estimators. Students learn the ideas behind pole placement, observers, and modern estimation without overloading the first course.', 11),
  ('143e5cb4-ef5d-4ff2-972e-336b5dfff0f4', '45241651-6d27-44f7-8908-f941a7418479', '88b58342-6025-4c1c-ac0b-455af456d4d5', 'subtopic'::public.curated_course_node_type, 'State Feedback and Pole Placement', 'Students learn how full-state feedback can assign closed-loop dynamics when a system is controllable.', 0),
  ('68d1ffc2-0eef-4b8f-a282-c637c49d67f3', '45241651-6d27-44f7-8908-f941a7418479', '143e5cb4-ef5d-4ff2-972e-336b5dfff0f4', 'concept'::public.curated_course_node_type, 'Feedback law structure', null, 0),
  ('1bb17679-56e4-43b4-83db-b60d3bfde33b', '45241651-6d27-44f7-8908-f941a7418479', '143e5cb4-ef5d-4ff2-972e-336b5dfff0f4', 'concept'::public.curated_course_node_type, 'Closed-loop eigenvalues', null, 1),
  ('d05b5c79-f868-4b0b-96ef-61114d4881a5', '45241651-6d27-44f7-8908-f941a7418479', '143e5cb4-ef5d-4ff2-972e-336b5dfff0f4', 'concept'::public.curated_course_node_type, 'Reference tracking and precompensation', null, 2),
  ('a97d490a-45f2-48ca-b332-160f869f0bd7', '45241651-6d27-44f7-8908-f941a7418479', '88b58342-6025-4c1c-ac0b-455af456d4d5', 'subtopic'::public.curated_course_node_type, 'Observers', 'Observers estimate states that cannot be measured directly, enabling state feedback in realistic systems.', 1),
  ('6a1749e9-94cf-4132-b37f-99aefff21449', '45241651-6d27-44f7-8908-f941a7418479', 'a97d490a-45f2-48ca-b332-160f869f0bd7', 'concept'::public.curated_course_node_type, 'Luenberger observer concept', null, 0),
  ('e02237f1-5139-41a4-958f-bd6a204682f8', '45241651-6d27-44f7-8908-f941a7418479', 'a97d490a-45f2-48ca-b332-160f869f0bd7', 'concept'::public.curated_course_node_type, 'Observer poles and error dynamics', null, 1),
  ('a19e774c-f0fd-47a7-a0fc-e35c6b626767', '45241651-6d27-44f7-8908-f941a7418479', 'a97d490a-45f2-48ca-b332-160f869f0bd7', 'concept'::public.curated_course_node_type, 'Separation principle overview', null, 2),
  ('ff3e4646-9e61-43ef-9793-9b2466f5b4e8', '45241651-6d27-44f7-8908-f941a7418479', '88b58342-6025-4c1c-ac0b-455af456d4d5', 'subtopic'::public.curated_course_node_type, 'Estimation and Kalman Filter Preview', 'Students get a conceptual bridge to stochastic estimation and sensor fusion.', 2),
  ('8b7d5b84-7c7d-48cd-b7d2-252fcaf74059', '45241651-6d27-44f7-8908-f941a7418479', 'ff3e4646-9e61-43ef-9793-9b2466f5b4e8', 'concept'::public.curated_course_node_type, 'Measurement noise and process uncertainty', null, 0),
  ('57de4907-cd9b-40c0-b46a-08ac3e561ca1', '45241651-6d27-44f7-8908-f941a7418479', 'ff3e4646-9e61-43ef-9793-9b2466f5b4e8', 'concept'::public.curated_course_node_type, 'Prediction-correction idea', null, 1),
  ('7d1e6eba-3872-46ef-8057-98f5a054ecd6', '45241651-6d27-44f7-8908-f941a7418479', 'ff3e4646-9e61-43ef-9793-9b2466f5b4e8', 'concept'::public.curated_course_node_type, 'Kalman filter applications in robotics, navigation, and embedded control', null, 2),
  ('d1662245-87c0-45ce-89d2-38cca794f768', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Digital Control and Sampled-Data Implementation', 'Most modern controllers run in software. This unit introduces sampling, discrete-time models, and implementation effects that matter when theory becomes code.', 12),
  ('c767e0ae-c578-4b8a-8c4a-893df7fc3d12', '45241651-6d27-44f7-8908-f941a7418479', 'd1662245-87c0-45ce-89d2-38cca794f768', 'subtopic'::public.curated_course_node_type, 'Sampling and Discretization', 'Students learn how continuous signals and controllers become sampled data systems.', 0),
  ('ef6e95e6-dbf7-4e62-85e2-f7a02cbb2c86', '45241651-6d27-44f7-8908-f941a7418479', 'c767e0ae-c578-4b8a-8c4a-893df7fc3d12', 'concept'::public.curated_course_node_type, 'Sampling period and Nyquist considerations', null, 0),
  ('a26617ba-2e85-4f67-9004-06ae913d49aa', '45241651-6d27-44f7-8908-f941a7418479', 'c767e0ae-c578-4b8a-8c4a-893df7fc3d12', 'concept'::public.curated_course_node_type, 'Zero-order hold', null, 1);
