values
  ('3bb90c28-0151-4e62-b254-1ecc7855d5b8', '45241651-6d27-44f7-8908-f941a7418479', 'c767e0ae-c578-4b8a-8c4a-893df7fc3d12', 'concept'::public.curated_course_node_type, 'Continuous-to-discrete model conversion', null, 2),
  ('010a99bd-d3a0-4b96-ac07-e6d0f48ea33a', '45241651-6d27-44f7-8908-f941a7418479', 'd1662245-87c0-45ce-89d2-38cca794f768', 'subtopic'::public.curated_course_node_type, 'Discrete-Time Transfer Functions and State Space', 'Discrete models let students analyze digital controllers with z-domain tools.', 1),
  ('23584d57-7674-4ea0-9c2d-66978b0416a6', '45241651-6d27-44f7-8908-f941a7418479', '010a99bd-d3a0-4b96-ac07-e6d0f48ea33a', 'concept'::public.curated_course_node_type, 'z-transform basics', null, 0),
  ('dce30e0d-071b-48e0-a9cb-a07a645a98fb', '45241651-6d27-44f7-8908-f941a7418479', '010a99bd-d3a0-4b96-ac07-e6d0f48ea33a', 'concept'::public.curated_course_node_type, 'Difference equations', null, 1),
  ('e99e9ba5-d0b9-4d4f-9fff-ee10e871773a', '45241651-6d27-44f7-8908-f941a7418479', '010a99bd-d3a0-4b96-ac07-e6d0f48ea33a', 'concept'::public.curated_course_node_type, 'Discrete poles and stability', null, 2),
  ('06c01c1c-a178-4d74-814b-e8d63dc8b3ed', '45241651-6d27-44f7-8908-f941a7418479', 'd1662245-87c0-45ce-89d2-38cca794f768', 'subtopic'::public.curated_course_node_type, 'Embedded Implementation Constraints', 'Students learn why real-time code, computation delay, quantization, and saturation affect control performance.', 2),
  ('ed5be0c3-46b1-4df2-bb53-ace3acba5694', '45241651-6d27-44f7-8908-f941a7418479', '06c01c1c-a178-4d74-814b-e8d63dc8b3ed', 'concept'::public.curated_course_node_type, 'Sample time selection', null, 0),
  ('6dc9035a-3fc7-4804-a877-e5e569440719', '45241651-6d27-44f7-8908-f941a7418479', '06c01c1c-a178-4d74-814b-e8d63dc8b3ed', 'concept'::public.curated_course_node_type, 'ADC/DAC resolution and quantization', null, 1),
  ('540d39d0-9792-458e-89e6-55330950c861', '45241651-6d27-44f7-8908-f941a7418479', '06c01c1c-a178-4d74-814b-e8d63dc8b3ed', 'concept'::public.curated_course_node_type, 'Latency, scheduling, and actuator limits', null, 2),
  ('478d6eb4-5469-4725-8c82-d84a35691eda', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Robustness, Practical Implementation, and Integrated Applications', 'The final unit pulls the course together around real design concerns: uncertainty, testing, validation, safety, and application-specific constraints.', 13),
  ('7da85eb9-2936-4ad2-80df-d5a47a266fb0', '45241651-6d27-44f7-8908-f941a7418479', '478d6eb4-5469-4725-8c82-d84a35691eda', 'subtopic'::public.curated_course_node_type, 'Robustness and Uncertainty', 'Students learn that models are imperfect and controllers must tolerate parameter variation, disturbances, and unmodeled dynamics.', 0),
  ('86dc5533-ca29-4ce1-af01-23c7cce2e7c0', '45241651-6d27-44f7-8908-f941a7418479', '7da85eb9-2936-4ad2-80df-d5a47a266fb0', 'concept'::public.curated_course_node_type, 'Sensitivity functions and margins', null, 0),
  ('845c9aef-73d0-47ae-b9f3-f878292769ff', '45241651-6d27-44f7-8908-f941a7418479', '7da85eb9-2936-4ad2-80df-d5a47a266fb0', 'concept'::public.curated_course_node_type, 'Parametric uncertainty', null, 1),
  ('037ad9b4-08c9-4fa0-b984-21149dae337a', '45241651-6d27-44f7-8908-f941a7418479', '7da85eb9-2936-4ad2-80df-d5a47a266fb0', 'concept'::public.curated_course_node_type, 'Unmodeled high-frequency dynamics', null, 2),
  ('dcab9193-58ab-4870-aadd-efc92edc9317', '45241651-6d27-44f7-8908-f941a7418479', '478d6eb4-5469-4725-8c82-d84a35691eda', 'subtopic'::public.curated_course_node_type, 'Testing, Tuning, and Validation', 'A controller is not finished until it is tested against requirements and operating conditions.', 1),
  ('a8d18640-0309-4b14-aff7-c96a91af7064', '45241651-6d27-44f7-8908-f941a7418479', 'dcab9193-58ab-4870-aadd-efc92edc9317', 'concept'::public.curated_course_node_type, 'Simulation and hardware-in-the-loop concepts', null, 0),
  ('26f228e7-3c3e-4c98-9f38-e33372fff1a3', '45241651-6d27-44f7-8908-f941a7418479', 'dcab9193-58ab-4870-aadd-efc92edc9317', 'concept'::public.curated_course_node_type, 'Step tests, frequency tests, and data logging', null, 1),
  ('e9d9d75f-5167-4c6a-b081-f01e26f40c9f', '45241651-6d27-44f7-8908-f941a7418479', 'dcab9193-58ab-4870-aadd-efc92edc9317', 'concept'::public.curated_course_node_type, 'Requirement verification and failure modes', null, 2),
  ('16463b00-de54-4a54-8748-3ba50f06e3ec', '45241651-6d27-44f7-8908-f941a7418479', '478d6eb4-5469-4725-8c82-d84a35691eda', 'subtopic'::public.curated_course_node_type, 'Integrated Control Applications', 'Capstone-style applications help students connect methods to engineering systems.', 2),
  ('105cc0b3-94d4-4ee2-b62c-2e2c738b27df', '45241651-6d27-44f7-8908-f941a7418479', '16463b00-de54-4a54-8748-3ba50f06e3ec', 'concept'::public.curated_course_node_type, 'Motor control, robotics, power electronics, process control', null, 0),
  ('94b736be-3eb6-498d-8554-c3e1186ba36c', '45241651-6d27-44f7-8908-f941a7418479', '16463b00-de54-4a54-8748-3ba50f06e3ec', 'concept'::public.curated_course_node_type, 'Aircraft/autopilot or vehicle control examples', null, 1),
  ('a807bde5-3be2-4c20-a400-45f2a53dff57', '45241651-6d27-44f7-8908-f941a7418479', '16463b00-de54-4a54-8748-3ba50f06e3ec', 'concept'::public.curated_course_node_type, 'Safety, fault detection, and fail-safe behavior', null, 2),
  ('029c75fe-2651-41ea-8e9b-a991dc6f96b7', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Optimal Control, LQR, and Model Predictive Control', 'This unit introduces optimization as a systematic way to balance tracking, regulation, actuator effort, and constraints. It gives graduate students a launch point for advanced optimal control while giving undergraduates the design intuition behind widely used modern methods.', 14),
  ('0fa9ce1d-b24b-41a5-9c24-a9d8469a442c', '45241651-6d27-44f7-8908-f941a7418479', '029c75fe-2651-41ea-8e9b-a991dc6f96b7', 'subtopic'::public.curated_course_node_type, 'Quadratic performance and LQR', 'Students learn how a quadratic objective converts design priorities into an optimal state-feedback law for a linear model.', 0),
  ('a1193005-a3ed-437f-9454-710adaad0c9f', '45241651-6d27-44f7-8908-f941a7418479', '0fa9ce1d-b24b-41a5-9c24-a9d8469a442c', 'concept'::public.curated_course_node_type, 'State and input penalty matrices', null, 0),
  ('a4528d8c-14df-43ea-b70a-2a7e7bad8ee0', '45241651-6d27-44f7-8908-f941a7418479', '0fa9ce1d-b24b-41a5-9c24-a9d8469a442c', 'concept'::public.curated_course_node_type, 'Finite- versus infinite-horizon objectives', null, 1),
  ('a39b6046-71cf-4fb8-b453-eecc4ee53c41', '45241651-6d27-44f7-8908-f941a7418479', '0fa9ce1d-b24b-41a5-9c24-a9d8469a442c', 'concept'::public.curated_course_node_type, 'Riccati equation intuition', null, 2),
  ('b379a2df-6818-44ce-909b-458b649fbd2f', '45241651-6d27-44f7-8908-f941a7418479', '0fa9ce1d-b24b-41a5-9c24-a9d8469a442c', 'concept'::public.curated_course_node_type, 'Closed-loop eigenstructure and tuning tradeoffs', null, 3),
  ('d923a8ab-2efe-40af-a4dc-7079ef579829', '45241651-6d27-44f7-8908-f941a7418479', '029c75fe-2651-41ea-8e9b-a991dc6f96b7', 'subtopic'::public.curated_course_node_type, 'Tracking, integral action, and reference management', 'Optimal regulation must be extended carefully when the goal is to follow commands without offset.', 1),
  ('3232fec5-5b5f-48e9-8053-9538c8206c57', '45241651-6d27-44f7-8908-f941a7418479', 'd923a8ab-2efe-40af-a4dc-7079ef579829', 'concept'::public.curated_course_node_type, 'Reference prefilters', null, 0),
  ('d8b786a5-0527-4dfa-83c3-ccff93aedd7d', '45241651-6d27-44f7-8908-f941a7418479', 'd923a8ab-2efe-40af-a4dc-7079ef579829', 'concept'::public.curated_course_node_type, 'Integral-state augmentation', null, 1),
  ('969535e0-cd60-4981-9502-7d8366396e31', '45241651-6d27-44f7-8908-f941a7418479', 'd923a8ab-2efe-40af-a4dc-7079ef579829', 'concept'::public.curated_course_node_type, 'Servo design', null, 2),
  ('ef8f52cc-131e-4a45-92bb-6a4a86e59c67', '45241651-6d27-44f7-8908-f941a7418479', 'd923a8ab-2efe-40af-a4dc-7079ef579829', 'concept'::public.curated_course_node_type, 'Offset-free tracking assumptions', null, 3),
  ('cfbd18a6-4d86-4a5b-8e56-b00a00606946', '45241651-6d27-44f7-8908-f941a7418479', '029c75fe-2651-41ea-8e9b-a991dc6f96b7', 'subtopic'::public.curated_course_node_type, 'Constraints and model predictive control', 'Students learn why receding-horizon optimization is valuable when inputs, states, outputs, and rates have hard limits.', 2),
  ('5b813028-251f-4f4b-886e-b17209c6a019', '45241651-6d27-44f7-8908-f941a7418479', 'cfbd18a6-4d86-4a5b-8e56-b00a00606946', 'concept'::public.curated_course_node_type, 'Prediction model and horizon', null, 0),
  ('ee6112e4-499c-4d98-8686-277c3f732a03', '45241651-6d27-44f7-8908-f941a7418479', 'cfbd18a6-4d86-4a5b-8e56-b00a00606946', 'concept'::public.curated_course_node_type, 'Input/state/output constraints', null, 1),
  ('477c35de-ac60-47d3-85d5-f1e9417285ee', '45241651-6d27-44f7-8908-f941a7418479', 'cfbd18a6-4d86-4a5b-8e56-b00a00606946', 'concept'::public.curated_course_node_type, 'Quadratic programming intuition', null, 2),
  ('fa4c6e12-fc69-4979-8dfd-d5a9de822d67', '45241651-6d27-44f7-8908-f941a7418479', 'cfbd18a6-4d86-4a5b-8e56-b00a00606946', 'concept'::public.curated_course_node_type, 'Recursive feasibility and terminal ingredients overview', null, 3),
  ('488eafc7-07fd-47bf-8186-c9b8b9cde300', '45241651-6d27-44f7-8908-f941a7418479', '029c75fe-2651-41ea-8e9b-a991dc6f96b7', 'subtopic'::public.curated_course_node_type, 'Optimal-design evaluation', 'Students compare optimization-based controllers with classical and pole-placement designs using consistent evidence.', 3),
  ('d21a26b8-3197-46e3-824e-a45b9e3b5d2b', '45241651-6d27-44f7-8908-f941a7418479', '488eafc7-07fd-47bf-8186-c9b8b9cde300', 'concept'::public.curated_course_node_type, 'Tracking versus effort metrics', null, 0),
  ('d29d5db8-430c-4ada-8571-1b1f9b1b4e75', '45241651-6d27-44f7-8908-f941a7418479', '488eafc7-07fd-47bf-8186-c9b8b9cde300', 'concept'::public.curated_course_node_type, 'Sensitivity to model mismatch', null, 1),
  ('20beee88-289a-4d9e-9802-44da750d9ed9', '45241651-6d27-44f7-8908-f941a7418479', '488eafc7-07fd-47bf-8186-c9b8b9cde300', 'concept'::public.curated_course_node_type, 'Computation time and solver failure', null, 2),
  ('a77956f2-ff87-4e98-baeb-d1109b990f94', '45241651-6d27-44f7-8908-f941a7418479', '488eafc7-07fd-47bf-8186-c9b8b9cde300', 'concept'::public.curated_course_node_type, 'Constraint activation and fallback behavior', null, 3),
  ('d71edba9-61f8-45bf-b5d4-7dcb15614f0b', '45241651-6d27-44f7-8908-f941a7418479', null, 'topic'::public.curated_course_node_type, 'Nonlinear Control, System Identification, and Data-Driven Methods', 'The final advanced unit shows where linear models come from, when they fail, and how data can improve them. The goal is disciplined awareness: students should know what these methods claim, what evidence they require, and when a specialized follow-on course is needed.', 15),
  ('1b000539-c951-4473-acac-821d8517a211', '45241651-6d27-44f7-8908-f941a7418479', 'd71edba9-61f8-45bf-b5d4-7dcb15614f0b', 'subtopic'::public.curated_course_node_type, 'Nonlinear dynamics and phase-plane reasoning', 'Students learn how equilibria, local linearization, trajectories, and invariant behavior reveal phenomena that a single transfer function cannot capture.', 0),
  ('bc527c02-3d99-4e83-94d0-e2ad10b50819', '45241651-6d27-44f7-8908-f941a7418479', '1b000539-c951-4473-acac-821d8517a211', 'concept'::public.curated_course_node_type, 'Equilibria and local models', null, 0),
  ('0cfe4bd2-8675-4e76-b2a7-2cd918c9efb4', '45241651-6d27-44f7-8908-f941a7418479', '1b000539-c951-4473-acac-821d8517a211', 'concept'::public.curated_course_node_type, 'Phase portraits and nullclines', null, 1),
  ('88011db7-97c3-4973-b3cc-fa5d96dd1935', '45241651-6d27-44f7-8908-f941a7418479', '1b000539-c951-4473-acac-821d8517a211', 'concept'::public.curated_course_node_type, 'Limit cycles and multiple equilibria', null, 2),
  ('5eef9933-9c99-4c4d-a040-cb163d965403', '45241651-6d27-44f7-8908-f941a7418479', '1b000539-c951-4473-acac-821d8517a211', 'concept'::public.curated_course_node_type, 'Local versus global conclusions', null, 3),
  ('5f155413-13e3-4144-add8-8f4a294a0f51', '45241651-6d27-44f7-8908-f941a7418479', 'd71edba9-61f8-45bf-b5d4-7dcb15614f0b', 'subtopic'::public.curated_course_node_type, 'Lyapunov stability and nonlinear control overview', 'Lyapunov functions provide an energy-like way to reason about stability without explicitly solving nonlinear differential equations.', 1),
  ('f6cbd8b6-7bf5-4eca-ae0c-5cfead204fdb', '45241651-6d27-44f7-8908-f941a7418479', '5f155413-13e3-4144-add8-8f4a294a0f51', 'concept'::public.curated_course_node_type, 'Positive-definite functions', null, 0),
