insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Feedback Systems: An Introduction for Scientists and Engineers', 'https://fbswiki.org/wiki/index.php/FBS', 'Astrom and Murray. Rigorous, readable bridge from modeling and classical feedback to state space, robustness, and design.', 0),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Feedback Control of Dynamic Systems', 'Pearson', 'Franklin, Powell, and Emami-Naeini for classical design, state space, digital control, and engineering applications.', 1),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Control Systems Engineering', 'Wiley', 'Nise offers accessible worked examples and strong support for undergraduate modeling and classical design.', 2),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Modern Control Engineering', 'Pearson', 'Ogata provides broad classical and modern coverage with detailed analysis and design examples.', 3),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Linear Systems Theory', 'Princeton University Press', 'Hespanha develops graduate-level state-space structure, stability, controllability, observability, and feedback.', 4),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Feedback Control Theory', 'Dover', 'Doyle, Francis, and Tannenbaum emphasize sensitivity, robustness, uncertainty, and fundamental limitations.', 5),
  ('45241651-6d27-44f7-8908-f941a7418479', 'textbook'::public.curated_course_resource_kind, 'Robust and Optimal Control', 'Prentice Hall', 'Zhou, Doyle, and Glover support advanced robust/optimal-control extensions and MS projects.', 6),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'MIT 2.14 Analysis and Design of Feedback Control Systems', 'https://ocw.mit.edu/courses/2-14-analysis-and-design-of-feedback-control-systems-spring-2014/', 'Laboratory-rich classical, state-space, multivariable, nonlinear, and digital control with an extended design case.', 7),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'MIT 16.30 Feedback Control Systems', 'https://ocw.mit.edu/courses/16-30-feedback-control-systems-fall-2010/', 'State-space design, estimation, output feedback, nonlinear analysis, uncertainty, and robustness.', 8),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'MIT 6.241J Dynamic Systems and Control', 'https://ocw.mit.edu/courses/6-241j-dynamic-systems-and-control-spring-2011/', 'Graduate MIMO linear systems, robust stability/performance, and optimal/robust design foundations.', 9),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'Control Tutorials for MATLAB and Simulink', 'https://ctms.engin.umich.edu/CTMS/', 'Practical plant examples for modeling, response, PID, root locus, frequency methods, and state space.', 10),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'Python Control Systems Library', 'https://python-control.readthedocs.io/', 'Open analysis and design environment for transfer functions, state space, frequency response, synthesis, and simulation.', 11),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'MATLAB Control System Toolbox', 'https://www.mathworks.com/products/control.html', 'Industry-standard modeling, analysis, tuning, estimation, and control-design workflows.', 12),
  ('45241651-6d27-44f7-8908-f941a7418479', 'website'::public.curated_course_resource_kind, 'IEEE Control Systems Society', 'https://www.ieeecss.org/', 'Research, standards, conferences, technical communities, and current directions in control.', 13),
  ('45241651-6d27-44f7-8908-f941a7418479', 'youtube'::public.curated_course_resource_kind, 'Brian Douglas', 'https://www.youtube.com/@BrianBDouglas', 'Exceptionally clear visual explanations of transfer functions, stability, root locus, Bode/Nyquist, PID, and state space.', 14),
  ('45241651-6d27-44f7-8908-f941a7418479', 'youtube'::public.curated_course_resource_kind, 'Steve Brunton', 'https://www.youtube.com/@Eigensteve', 'Dynamic systems, state-space control, estimation, system identification, nonlinear methods, and data-driven modeling.', 15),
  ('45241651-6d27-44f7-8908-f941a7418479', 'youtube'::public.curated_course_resource_kind, 'MIT OpenCourseWare', 'https://www.youtube.com/@mitocw', 'University lectures and demonstrations spanning mechanical, electrical, aerospace, and graduate control.', 16),
  ('45241651-6d27-44f7-8908-f941a7418479', 'youtube'::public.curated_course_resource_kind, 'MATLAB', 'https://www.youtube.com/@MATLAB', 'Practical Simulink, PID tuning, control design, system identification, and deployment workflows.', 17);
